<!--
 * 任务执行日志（列表页 / 只读）
 *
 * @path apps\cronjob-web\src\views\jobLog\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务执行日志（列表页 / 只读）
 * <p>消费后端契约 JobController.pageLog（src/api/job.ts，auto-generated by bash/gen-contract.py），
 * 纯只读「执行日志」页：分页查询 + 按任务标识/状态筛选，无任何新增/编辑/删除操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { ElTag } from 'element-plus';
import { h } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { pageLog } from '#/api/job';
import type { JobLogVO } from '#/api/models';

defineOptions({ name: 'JobLogManagement' });

const gridOptions: VxeGridProps<JobLogVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'jobKey', title: '任务标识', width: 140 },
    {
      field: 'status',
      title: '状态',
      width: 100,
      slots: {
        default: ({ row }) => {
          const log = row as JobLogVO;
          const isSuccess = log.status === 'SUCCESS' || log.status === '0';
          return h(
            ElTag,
            { type: isSuccess ? 'success' : 'danger' },
            () => log.status ?? '-',
          );
        },
      },
    },
    { field: 'startTime', title: '开始时间', width: 170 },
    { field: 'endTime', title: '结束时间', width: 170 },
    { field: 'durationMs', title: '耗时(ms)', width: 100 },
    { field: 'triggerType', title: '触发类型', width: 110 },
    { field: 'errorMessage', title: '错误信息', min-width: 180 },
    { field: 'createdAt', title: '创建时间', width: 170 },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const res = await pageLog({
          pageNum: pageInfo.currentPage,
          pageSize: pageInfo.pageSize,
          ...formValues,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'jobKey', title: '任务标识', itemRender: { name: 'Input', props: { placeholder: '任务标识' } } },
      { field: 'status', title: '状态', itemRender: { name: 'Input', props: { placeholder: '状态' } } },
    ],
  },
};

const [Grid] = useYDSZVxeGrid({ gridOptions });
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="执行日志" />
  </Page>
</template>